import{_ as a,o as s,c as n,a2 as r}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Project structure","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/project-structure","contentType":"concept","prev":false,"next":{"text":"Module boundaries","link":"/en/architecture/module-boundaries"}},"headers":[],"relativePath":"en/architecture/project-structure.md","filePath":"en/architecture/project-structure.md"}'),t={name:"en/architecture/project-structure.md"};function p(i,e,o,c,d,l){return s(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="project-structure" tabindex="-1">Project structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project structure&quot;">​</a></h1><p>Lab Word runs one TypeScript service and a Web application. Persistent Labs, assets, layouts, device programs, observations, records and trends use the shared Member/Agent HTTP contract.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/</span></span>
<span class="line"><span>  server/src/              Node service, CLI and lifecycle composition</span></span>
<span class="line"><span>  web/src/app.ts           Direct Lab application configuration</span></span>
<span class="line"><span>  web/src/router.tsx       Web routing adapter</span></span>
<span class="line"><span>  desktop/src/             Shared Electron shell source</span></span>
<span class="line"><span>  docs/.vitepress/         Bilingual documentation site</span></span>
<span class="line"><span>packages/</span></span>
<span class="line"><span>  server/src/platform/     Embedded DB, local bytes and HTTP adapters</span></span>
<span class="line"><span>  server/src/core/         Identity, members, keys, files, audit and limits</span></span>
<span class="line"><span>  server/src/lab/          Assets, World, Devices, History and Records</span></span>
<span class="line"><span>  views/src/lab/           Workbench, assets and 3D views</span></span>
<span class="line"><span>  views/src/shell/         Shared navigation, preferences and messages</span></span>
<span class="line"><span>  ui/src/                  Shared components and styles</span></span>
<span class="line"><span>  contracts/               Node-generated OpenAPI and TypeScript DTOs</span></span>
<span class="line"><span>  sdk/                     Generated HTTP client and Lab SSE transport</span></span>
<span class="line"><span>scripts/                   Development, checks, builds and operations</span></span>
<span class="line"><span>docs/                      Guides, domain vocabulary and decisions</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/web/src/app.ts" target="_blank" rel="noreferrer">application entry</a> imports the <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/views/src/lab/app.tsx" target="_blank" rel="noreferrer">Lab application</a> directly. Its <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/web/src/router.tsx" target="_blank" rel="noreferrer">router</a> supplies navigation and API-client ports. The <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">shell interface</a> describes pages, navigation and bilingual messages. Lab opens after login; <code>/</code> remains the shared home. Heavy views and 3D code load on demand.</p><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/server/src/runtime.ts" target="_blank" rel="noreferrer">runtime</a> owns service initialization and shutdown. Database drivers and migrations stay in <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/server/src/platform/db/index.ts" target="_blank" rel="noreferrer">platform/db</a>. Platform Core does not import Lab. Web uses the generated SDK; server database code never enters the Web bundle. Retired source and infrastructure are preserved only at <code>legacy-rust-final</code>. Current commands use Node.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>Run from the repository root. Boundary checks cover package dependencies and the TypeScript service, and Node table/SDK ownership. See <a href="./../testing/feedback-loop">development and validation</a>, <a href="./module-boundaries">module boundaries</a> and the <a href="./../guides/lab-viewer">Lab guide</a>.</p><hr><p>Source version：<code>d21b97585cfd</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/architecture/project-structure.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,9)])])}const h=a(t,[["render",p]]);export{u as __pageData,h as default};
